const response = $input.first().json;
if (typeof response.message?.content !== 'string') throw new Error('Ollama returned no message content');
const result = JSON.parse(response.message.content);
const expected = { company: 'Example Foods', technology: 'ExampleShield', status: 'pilot', source_id: 'demo-1' };
for (const [key, value] of Object.entries(expected)) {
  if (result[key] !== value) throw new Error(`Extraction mismatch for ${key}: ${JSON.stringify(result[key])}`);
}
return [{ json: { passed: true, synthetic_evidence: true, extracted: result, model: response.model, next_step: 'Review the extraction, then build the company input form together.' } }];
